-- ============================================================================
-- RUN_ALL.sql: scripts 001 to 007 in order (generated by concatenating them).
-- Paste into Supabase Dashboard -> SQL Editor and run. Safe to run more than once.
-- The numbered files are the source; regenerate this file if you edit them.
-- ============================================================================


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 001_email_uniqueness.sql <<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<
-- ============================================================================
-- 001 · One account per email (any role, any status) + blocked emails
--
-- Run in: Supabase Dashboard → SQL Editor. Safe to run more than once.
-- App code: src/lib/auth/email.ts (works before this script, but without the
-- database guarantee and without seeing auth.users directly).
-- ============================================================================

-- 0. Pre-check: both queries must return no rows, otherwise the unique indexes
--    below cannot be created. (Checked 2026-11-25: no duplicates.)
select lower(email) as email, count(*) from public.user_accounts where email is not null group by 1 having count(*) > 1;
select lower(email) as email, count(*) from public.profiles      where email is not null group by 1 having count(*) > 1;

-- 1. The database refuses a second account row with the same address, whatever its letter case.
create unique index if not exists user_accounts_email_lower_key on public.user_accounts (lower(email));
create unique index if not exists profiles_email_lower_key      on public.profiles (lower(email));

-- 2. Emails that can never register again: accounts deleted after a suspension or termination.
--    Only a SHA-256 hash is stored (see emailHash() in src/lib/auth/email.ts), never the address.
create table if not exists public.blocked_emails (
  email_hash  text primary key,
  reason      text not null,
  account_id  uuid,
  created_at  timestamptz not null default now()
);
alter table public.blocked_emails enable row level security;
-- No policies on purpose: only the server (service role, which bypasses RLS) can read or write it.
revoke all on public.blocked_emails from anon, authenticated;

-- 3. One call that also sees auth.users (which the API cannot query).
create or replace function public.email_registration_status(p_email text, p_email_hash text)
returns text
language sql
stable
security definer
set search_path = public, auth
as $$
  select case
    when exists (select 1 from public.blocked_emails b where b.email_hash = p_email_hash) then 'blocked'
    when exists (select 1 from auth.users u where lower(u.email) = lower(trim(p_email)))
      or exists (select 1 from public.user_accounts a where lower(a.email) = lower(trim(p_email)))
      or exists (select 1 from public.profiles p where lower(p.email) = lower(trim(p_email)))
    then 'in_use'
    else 'available'
  end;
$$;
revoke all on function public.email_registration_status(text, text) from public, anon, authenticated;
grant execute on function public.email_registration_status(text, text) to service_role;

-- Check: expect two rows (both indexes) and 'in_use' for an address that exists.
select indexname from pg_indexes where indexname in ('user_accounts_email_lower_key', 'profiles_email_lower_key');
select public.email_registration_status('admin@justicia.ph', 'x') as admin_email_status;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 002_rate_limits.sql <<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<
-- ============================================================================
-- 002 · Shared rate-limit counters
--
-- App code: src/lib/security/rateLimit.ts. Until this script runs, each server
-- instance keeps its own in-memory counter (weaker on Vercel, where requests
-- spread across instances). Keys arrive already hashed; no IPs or emails stored.
-- ============================================================================

create table if not exists public.rate_limit_hits (
  key           text        not null,
  window_start  timestamptz not null,
  hits          integer     not null default 0,
  primary key (key, window_start)
);
alter table public.rate_limit_hits enable row level security;
revoke all on public.rate_limit_hits from anon, authenticated;

-- Counts one hit in the current fixed window and says whether it is still allowed.
create or replace function public.hit_rate_limit(p_key text, p_limit integer, p_window_seconds integer)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_window timestamptz := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
  v_hits   integer;
begin
  insert into public.rate_limit_hits as r (key, window_start, hits)
  values (p_key, v_window, 1)
  on conflict (key, window_start) do update set hits = r.hits + 1
  returning hits into v_hits;

  -- Occasional cleanup of old windows.
  if random() < 0.01 then
    delete from public.rate_limit_hits where window_start < now() - interval '2 days';
  end if;

  return jsonb_build_object(
    'allowed', v_hits <= p_limit,
    'retry_after', greatest(1, ceil(extract(epoch from (v_window + make_interval(secs => p_window_seconds) - now())))::int)
  );
end;
$$;
revoke all on function public.hit_rate_limit(text, integer, integer) from public, anon, authenticated;
grant execute on function public.hit_rate_limit(text, integer, integer) to service_role;

-- Check: the first call is allowed, the third with limit 2 is not.
select public.hit_rate_limit('manual-check', 2, 60) as first_call;
select public.hit_rate_limit('manual-check', 2, 60);
select public.hit_rate_limit('manual-check', 2, 60) as third_call_should_not_be_allowed;
delete from public.rate_limit_hits where key = 'manual-check';


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 003_access_rules.sql <<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<
-- ============================================================================
-- 003 · Access-rule (RLS) fixes found by scripts/rls-audit.js on 2026-11-25
--
-- Failures this fixes:
--   1. Anyone, even signed out, could read every user_accounts row (emails, phones, roles).
--   2. A client could insert a payments row marked "paid".
--   3. A pending lawyer could set their own verification_status to 'approved' and list
--      themselves in Find a Lawyer, straight from the browser.
--   4. Signed-out visitors could read pending lawyer applications (lawyer_profiles).
--
-- The app's server code uses the service-role key (which bypasses RLS) for all writes, so
-- removing browser write access does not break any feature. Re-run scripts/rls-audit.js after.
-- Safe to run more than once.
-- ============================================================================

-- Helper: true when the request comes from a browser session (anon key or a signed-in user's JWT)
-- rather than the server (service role) or the SQL editor.
create or replace function public.is_browser_request()
returns boolean
language sql
stable
as $$
  select coalesce(auth.role(), '') in ('anon', 'authenticated');
$$;

-- ─── 1. user_accounts: each user reads only their own row; admins read all ──
do $$
declare r record;
begin
  for r in select policyname from pg_policies where schemaname = 'public' and tablename = 'user_accounts' loop
    execute format('drop policy %I on public.user_accounts', r.policyname);
  end loop;
end $$;
alter table public.user_accounts enable row level security;
create policy user_accounts_select_own_or_admin on public.user_accounts
  for select to authenticated
  using (auth.uid() = id or public.is_admin());
-- No insert/update/delete policies: account rows are written by the server and the sign-up trigger.

-- ─── 2. payments: participants and admins may read; nobody writes from the browser ──
do $$
declare r record;
begin
  for r in select policyname from pg_policies where schemaname = 'public' and tablename = 'payments' loop
    execute format('drop policy %I on public.payments', r.policyname);
  end loop;
end $$;
alter table public.payments enable row level security;
create policy payments_select_participants on public.payments
  for select to authenticated
  using (payer_id = auth.uid() or payee_id = auth.uid() or public.is_admin());

-- ─── 3. lawyer_profiles: public sees approved + listed lawyers; owners and admins see their rows ──
do $$
declare r record;
begin
  for r in select policyname from pg_policies where schemaname = 'public' and tablename = 'lawyer_profiles' loop
    execute format('drop policy %I on public.lawyer_profiles', r.policyname);
  end loop;
end $$;
alter table public.lawyer_profiles enable row level security;
create policy lawyer_profiles_public_read on public.lawyer_profiles
  for select to anon, authenticated
  using (verification_status = 'approved' and is_visible = true);
create policy lawyer_profiles_own_read on public.lawyer_profiles
  for select to authenticated
  using (auth.uid() = user_id);
create policy lawyer_profiles_admin_read on public.lawyer_profiles
  for select to authenticated
  using (public.is_admin());
-- Profile edits, registration and verification decisions all go through the server.

-- Defence in depth: even if a write policy is added later, a browser session can never change
-- verification fields, ratings or its own listing before approval.
create or replace function public.guard_lawyer_profile_fields()
returns trigger
language plpgsql
as $$
begin
  if not public.is_browser_request() or public.is_admin() then
    return new;
  end if;
  if tg_op = 'INSERT' then
    new.verification_status := 'draft';
    new.is_visible := false;
    new.reviewed_by := null;
    new.reviewed_at := null;
    new.admin_notes := null;
    new.rejection_reason := null;
    new.rating_avg := null;
    new.rating_count := 0;
    return new;
  end if;
  if new.verification_status is distinct from old.verification_status
     or new.reviewed_by is distinct from old.reviewed_by
     or new.reviewed_at is distinct from old.reviewed_at
     or new.admin_notes is distinct from old.admin_notes
     or new.rejection_reason is distinct from old.rejection_reason
     or new.submitted_at is distinct from old.submitted_at
     or new.rating_avg is distinct from old.rating_avg
     or new.rating_count is distinct from old.rating_count
     or (new.is_visible is distinct from old.is_visible and old.verification_status <> 'approved')
  then
    raise exception 'Verification fields can only be changed by Justicia.' using errcode = '42501';
  end if;
  return new;
end;
$$;
drop trigger if exists trg_guard_lawyer_profile_fields on public.lawyer_profiles;
create trigger trg_guard_lawyer_profile_fields
  before insert or update on public.lawyer_profiles
  for each row execute function public.guard_lawyer_profile_fields();

-- Check: expect the policies listed below and no others on these three tables.
select tablename, policyname, cmd, roles
from pg_policies
where schemaname = 'public' and tablename in ('user_accounts', 'payments', 'lawyer_profiles')
order by tablename, policyname;


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 004_lawyer_verification_documents.sql <<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<
-- ============================================================================
-- 004 · Lawyer verification documents (proof uploads, review status, versions)
--
-- App code: src/lib/lawyer/verificationDocuments.ts and
-- src/app/actions/lawyerVerificationDocs.ts. Files go to the private
-- `lawyer-credentials` bucket; this table holds one row per uploaded file.
-- REQUIRED before lawyers can upload documents or submit applications.
-- ============================================================================

alter table public.lawyer_verification_documents
  add column if not exists original_filename   text,
  add column if not exists mime_type           text,
  add column if not exists size_bytes          bigint,
  add column if not exists checksum_sha256     text,
  add column if not exists submission_version  integer not null default 1,
  add column if not exists review_status       text    not null default 'uploaded',
  add column if not exists review_note         text,
  add column if not exists reviewed_by         uuid references public.user_accounts(id),
  add column if not exists reviewed_at         timestamptz,
  add column if not exists superseded_at       timestamptz,
  add column if not exists uploaded_by         uuid;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'lvd_review_status_check') then
    alter table public.lawyer_verification_documents
      add constraint lvd_review_status_check
      check (review_status in ('uploaded', 'under_review', 'accepted', 'rejected'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'lvd_size_check') then
    alter table public.lawyer_verification_documents
      add constraint lvd_size_check check (size_bytes is null or (size_bytes > 0 and size_bytes <= 10485760));
  end if;
end $$;

create index if not exists lvd_lawyer_current_idx
  on public.lawyer_verification_documents (lawyer_id, doc_type)
  where superseded_at is null;

-- Access: the lawyer reads their own documents, admins read all. Uploads, replacements and
-- review decisions go through the server (service role), which logs every view.
do $$
declare r record;
begin
  for r in select policyname from pg_policies where schemaname = 'public' and tablename = 'lawyer_verification_documents' loop
    execute format('drop policy %I on public.lawyer_verification_documents', r.policyname);
  end loop;
end $$;
alter table public.lawyer_verification_documents enable row level security;
create policy lvd_select_own on public.lawyer_verification_documents
  for select to authenticated using (lawyer_id = auth.uid());
create policy lvd_select_admin on public.lawyer_verification_documents
  for select to authenticated using (public.is_admin());

-- The bucket must stay private (files are opened only through 5-minute signed links).
update storage.buckets set public = false where id = 'lawyer-credentials';

-- Check: expect the new columns and public = false.
select column_name from information_schema.columns
where table_schema = 'public' and table_name = 'lawyer_verification_documents'
order by ordinal_position;
select id, public from storage.buckets where id = 'lawyer-credentials';


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 005_booking_integrity.sql <<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<
-- ============================================================================
-- 005 · Booking integrity: no overlapping bookings, eligibility on insert,
--       allowed status changes, and an audit entry for every status change.
--
-- Depends on 003 (public.is_browser_request). Safe to run more than once.
-- ============================================================================

-- 0. Pre-check: both must return no rows, or step 2 fails. (Checked 2026-11-25: none.)
select a.id, b.id as overlaps_with, a.lawyer_id
from public.consultations a
join public.consultations b
  on a.lawyer_id = b.lawyer_id and a.id < b.id
 and tstzrange(a.scheduled_start, a.scheduled_end, '[)') && tstzrange(b.scheduled_start, b.scheduled_end, '[)')
where a.status in ('pending', 'awaiting_client_confirmation', 'confirmed')
  and b.status in ('pending', 'awaiting_client_confirmation', 'confirmed')
  and a.scheduled_start is not null and a.scheduled_end is not null
  and b.scheduled_start is not null and b.scheduled_end is not null;
select a.id, b.id as overlaps_with, a.client_id
from public.consultations a
join public.consultations b
  on a.client_id = b.client_id and a.id < b.id
 and tstzrange(a.scheduled_start, a.scheduled_end, '[)') && tstzrange(b.scheduled_start, b.scheduled_end, '[)')
where a.status in ('pending', 'awaiting_client_confirmation', 'confirmed')
  and b.status in ('pending', 'awaiting_client_confirmation', 'confirmed')
  and a.scheduled_start is not null and a.scheduled_end is not null
  and b.scheduled_start is not null and b.scheduled_end is not null;

-- 1. Range types over uuid need btree_gist.
create extension if not exists btree_gist with schema extensions;

-- 2. A lawyer (and a client) can never hold two active bookings whose times overlap, even when
--    two requests arrive at the same moment. bookConsultationAction already turns the resulting
--    error (23P01) into "this slot was just reserved".
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'consultations_no_lawyer_overlap') then
    alter table public.consultations
      add constraint consultations_no_lawyer_overlap
      exclude using gist (lawyer_id with =, tstzrange(scheduled_start, scheduled_end, '[)') with &&)
      where (status in ('pending', 'awaiting_client_confirmation', 'confirmed')
             and scheduled_start is not null and scheduled_end is not null);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'consultations_no_client_overlap') then
    alter table public.consultations
      add constraint consultations_no_client_overlap
      exclude using gist (client_id with =, tstzrange(scheduled_start, scheduled_end, '[)') with &&)
      where (status in ('pending', 'awaiting_client_confirmation', 'confirmed')
             and scheduled_start is not null and scheduled_end is not null);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'consultations_time_order') then
    alter table public.consultations
      add constraint consultations_time_order
      check (scheduled_start is null or scheduled_end is null or scheduled_end > scheduled_start) not valid;
  end if;
end $$;

-- 3. Reads a JSON text column without failing on bad JSON.
create or replace function public.safe_jsonb(p text)
returns jsonb
language plpgsql
immutable
as $$
begin
  return p::jsonb;
exception when others then
  return null;
end;
$$;

-- 4. Eligibility, allowed status changes and the status-change audit trail.
--    Allowed (matches src/app/actions/consultationActions.ts):
--      pending                      → awaiting_client_confirmation | declined | cancelled
--      awaiting_client_confirmation → confirmed | cancelled
--      confirmed                    → completed | cancelled
--      declined, cancelled, completed are final.
--    Requests from the SQL editor (no JWT role) are allowed, for audited manual corrections.
create or replace function public.guard_consultation()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_caller   text := coalesce(auth.role(), '');
  v_allowed  boolean;
  v_actor    uuid;
  v_meta     jsonb;
begin
  if tg_op = 'INSERT' then
    if v_caller <> '' and new.status <> 'pending' then
      raise exception 'New consultations start as pending.' using errcode = '23514';
    end if;
    if v_caller <> '' then
      if not exists (
        select 1 from public.lawyer_profiles lp
        where lp.user_id = new.lawyer_id and lp.verification_status = 'approved'
      ) or exists (
        select 1 from public.profiles p where p.user_id = new.lawyer_id and p.account_status <> 'active'
      ) then
        raise exception 'This attorney is not accepting bookings.' using errcode = 'P0001';
      end if;
      if exists (select 1 from public.profiles p where p.user_id = new.client_id and p.account_status <> 'active') then
        raise exception 'This account cannot book consultations.' using errcode = 'P0001';
      end if;
    end if;
    return new;
  end if;

  if new.status is not distinct from old.status then
    return new;
  end if;

  v_allowed := case old.status
    when 'pending' then new.status in ('awaiting_client_confirmation', 'declined', 'cancelled')
    when 'awaiting_client_confirmation' then new.status in ('confirmed', 'cancelled')
    when 'confirmed' then new.status in ('completed', 'cancelled')
    else false
  end;
  if not v_allowed and v_caller <> '' then
    raise exception 'A consultation cannot change from % to %.', old.status, new.status using errcode = '23514';
  end if;

  v_meta := public.safe_jsonb(new.concern_summary);
  v_actor := case
    when auth.uid() is not null then auth.uid()
    when new.status = 'cancelled' then new.cancelled_by
    when new.status in ('awaiting_client_confirmation', 'declined', 'confirmed') then new.lawyer_id
    else null
  end;
  if v_actor is not null and not exists (select 1 from public.user_accounts where id = v_actor) then
    v_actor := null;
  end if;

  insert into public.audit_log (actor_id, action, target_type, target_id, details)
  values (
    v_actor,
    'consultation.status_changed',
    'consultation',
    new.id::text,
    jsonb_build_object(
      'from', old.status,
      'to', new.status,
      'reason', coalesce(v_meta ->> 'cancellationReason', v_meta ->> 'declineReason'),
      'source', case when v_caller = '' then 'manual_correction' else v_caller end
    )
  );
  return new;
end;
$$;
drop trigger if exists trg_guard_consultation on public.consultations;
create trigger trg_guard_consultation
  before insert or update on public.consultations
  for each row execute function public.guard_consultation();

-- Check: expect three constraints and the trigger.
select conname from pg_constraint where conname in ('consultations_no_lawyer_overlap', 'consultations_no_client_overlap', 'consultations_time_order');
select tgname from pg_trigger where tgname = 'trg_guard_consultation';


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 006_reviews_integrity.sql <<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<
-- ============================================================================
-- 006 · Reviews: one per consultation, references and rating cannot change,
--       replies only by the reviewed lawyer, hiding only by admins, no deletes
--       from the browser. (Reviews on unfinished consultations are already refused
--       by the existing trigger from 0007; confirmed by scripts/rls-audit.js.)
--
-- Depends on 003 (public.is_browser_request). Safe to run more than once.
-- ============================================================================

-- Pre-check: must return no rows. (Checked 2026-11-25: there are no reviews yet.)
select consultation_id, count(*) from public.reviews where consultation_id is not null group by 1 having count(*) > 1;

create unique index if not exists reviews_one_per_consultation
  on public.reviews (consultation_id)
  where consultation_id is not null;

create or replace function public.guard_review()
returns trigger
language plpgsql
as $$
begin
  if not public.is_browser_request() or public.is_admin() then
    return coalesce(new, old);
  end if;
  if tg_op = 'DELETE' then
    raise exception 'Reviews cannot be deleted.' using errcode = '42501';
  end if;
  if new.consultation_id is distinct from old.consultation_id
     or new.client_id is distinct from old.client_id
     or new.lawyer_id is distinct from old.lawyer_id
     or new.rating is distinct from old.rating
     or new.comment is distinct from old.comment
     or new.created_at is distinct from old.created_at
  then
    raise exception 'A review cannot be edited after it is posted.' using errcode = '42501';
  end if;
  if (new.counsel_reply is distinct from old.counsel_reply or new.counsel_replied_at is distinct from old.counsel_replied_at)
     and auth.uid() is distinct from old.lawyer_id
  then
    raise exception 'Only the reviewed lawyer can reply.' using errcode = '42501';
  end if;
  if new.is_hidden is distinct from old.is_hidden then
    raise exception 'Only administrators can hide reviews.' using errcode = '42501';
  end if;
  return new;
end;
$$;
drop trigger if exists trg_guard_review on public.reviews;
create trigger trg_guard_review
  before update or delete on public.reviews
  for each row execute function public.guard_review();

-- Check
select indexname from pg_indexes where indexname = 'reviews_one_per_consultation';
select tgname from pg_trigger where tgname = 'trg_guard_review';


-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 007_profile_fields.sql <<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<
-- ============================================================================
-- 007 · Client profile fields: city/province, consultation language, preferred contact
--       method and time. (profiles.preferred_language already exists, but its check constraint
--       only allows 'en' | 'fil': it is the interface language, kept for the later language
--       feature, so consultation language gets its own column.)
--
-- App code: src/app/actions/profileExtrasActions.ts. Lawyers see these only for
-- clients they have a consultation with (checked on the server).
-- ============================================================================

alter table public.profiles
  add column if not exists city_province         text,
  add column if not exists consultation_language text,
  add column if not exists contact_method        text,
  add column if not exists contact_time          text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_contact_method_check') then
    alter table public.profiles add constraint profiles_contact_method_check
      check (contact_method is null or contact_method in ('messages', 'email', 'phone_call', 'sms'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'profiles_contact_time_check') then
    alter table public.profiles add constraint profiles_contact_time_check
      check (contact_time is null or contact_time in ('morning', 'afternoon', 'evening', 'anytime'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'profiles_consultation_language_check') then
    alter table public.profiles add constraint profiles_consultation_language_check
      check (consultation_language is null or consultation_language in
        ('English', 'Filipino', 'Cebuano', 'Ilocano', 'Hiligaynon', 'Waray', 'Kapampangan', 'Bikolano'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'profiles_city_province_length') then
    alter table public.profiles add constraint profiles_city_province_length
      check (city_province is null or char_length(city_province) <= 120);
  end if;
end $$;

-- Check
select column_name from information_schema.columns
where table_schema = 'public' and table_name = 'profiles'
  and column_name in ('city_province', 'consultation_language', 'contact_method', 'contact_time');
